#include <iostream>
#include <array>
#include <algorithm>


int main() {
    std::array<int,4> a{}; for(int& x:a)if(!(std::cin>>x))return 1; int k{}; if(!(std::cin>>k)||k<0)return 1; std::rotate(a.begin(),a.begin()+k%4,a.end()); for(int i=0;i<4;++i)std::cout<<(i?" ":"")<<a[i]; std::cout<<'\n';
}
